namespace unifiedBackup {
static QString observation(QString s){return s=="baseline-observed"?"当前仍与开始时一致，提交归属未确认":s=="target-observed-unattributed"?"当前与目标相符，但缺可归属的提交回执":s=="different-current-state"?"当前数据另有变化，未覆盖或回滚":s;}
static QString stamp(){return QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs);}
static QString stateLabel(QString s){static const QMap<QString,QString> labels{{"blocked","不可恢复"},{"ready","等待确认"},{"pending","尚未执行"},{"running","可继续下一域"},{"applying","提交结果待核实"},{"uncertain","结果未确认，已停止"},{"failed","失败，已停止"},{"completed","已完成"},{"complete","本次所选域已完成"},{"unchanged","无变更"},{"stopped","已停止"},{"outcome-unverified","结果未确认"}};return labels.value(s,s);}
static QString planText(QJsonObject,const QMap<QString,QString>&);static QString receiptText(QJsonObject);
Page::Page(std::shared_ptr<Coordinator> c,std::shared_ptr<AsyncLane> a,std::function<void()> pick,std::function<void(QByteArray,QJsonObject)> sink,QWidget*parent):QWidget(parent),coordinator(std::move(c)),lane(std::move(a)),runner(lane->runner()),chooseFile(std::move(pick)),receiveExport(std::move(sink)){
 need(bool(coordinator),"协调器缺失");setObjectName("unifiedBackupPage");auto layout=new QVBoxLayout(this);
 auto intro=new QLabel("统一备份与逐项恢复\n请选择确切范围。不同模块分别保存；已完成项不会因后项失败自动撤回。人工龙头仅合并新增。完整文件最多32 MiB，单项最多8 MiB，人工配置最多2 MiB。",this);intro->setWordWrap(true);layout->addWidget(intro);
 auto scroll=new QScrollArea(this);scroll->setWidgetResizable(true);auto body=new QWidget(scroll);auto options=new QVBoxLayout(body);
 for(auto v:coordinator->catalog()){auto d=v.toObject();names[d["id"].toString()]=d["label"].toString();auto check=new QCheckBox(d["label"].toString(),body);check->setObjectName(d["id"].toString());check->setProperty("exportReady",d["exportReady"].toBool());choices<<check;options->addWidget(check);auto text=new QLabel(d["scope"].toString()+"\n"+d["reason"].toString(),body);text->setWordWrap(true);options->addWidget(text);connect(check,&QCheckBox::toggled,this,[this]{cancelPreview();});}
 scroll->setWidget(body);layout->addWidget(scroll,1);auto buttons=new QGridLayout;int n=0;
 auto button=[&](QString text,QString id){auto p=new QPushButton(text,this);p->setObjectName(id);buttons->addWidget(p,n/2,n%2);++n;return p;};
 exportButton=button("生成所选备份","exportBackup");openButton=button("选择备份文件","openBackup");previewButton=button("校验并预览所选项","previewBackup");cancelButton=button("取消本次预览","cancelBackup");beginButton=button("保存恢复前备份并开始","beginBackup");nextButton=button("执行下一项","nextBackup");stopButton=button("停止后续项","stopBackup");readButton=button("重读保存的回执","readReceipt");layout->addLayout(buttons);
 ack=new QCheckBox("已核对逐项差异；理解各项分别保存，失败后需重新核对",this);ack->setObjectName("ackBackup");layout->addWidget(ack);connect(ack,&QCheckBox::toggled,this,[this]{refresh();});
 details=new QTextEdit(this);details->setReadOnly(true);details->setObjectName("backupDetails");details->setPlainText("尚未读取数据。未接入的保存或回执功能将禁用确认。");layout->addWidget(details,2);auto paging=new QHBoxLayout;previousText=new QPushButton("上一段",this);nextText=new QPushButton("下一段",this);previousText->setObjectName("previousPreviewText");nextText->setObjectName("nextPreviewText");paging->addWidget(previousText);paging->addWidget(nextText);layout->addLayout(paging);connect(previousText,&QPushButton::clicked,this,[this]{textOffset=qMax(0,textOffset-32768);renderText();});connect(nextText,&QPushButton::clicked,this,[this]{textOffset+=32768;renderText();});
 connect(exportButton,&QPushButton::clicked,this,[this]{auto ids=selected();auto core=coordinator;auto bytes=std::make_shared<QByteArray>();run({false,ids.contains("watchlist-config")},[core,ids,bytes]{auto b=core->exportSelected(ids,stamp());*bytes=encode(b);auto summary=exportSummary(*bytes);summary["display"]=exportPreviewText(summary);return summary;},[this,bytes](QJsonObject summary,QString){receiveExport(*bytes,summary);showText("已生成所选备份，尚未写入文件。\n完整性校验："+summary["sha256"].toString());});});
 connect(openButton,&QPushButton::clicked,this,[this]{chooseFile();});
 connect(previewButton,&QPushButton::clicked,this,[this]{auto core=coordinator;auto b=bundle;auto ids=selected();auto labels=names;auto id=QUuid::createUuid().toString(QUuid::WithoutBraces);run({false,ids.contains("watchlist-config")},[core,b,ids,id,labels]{auto p=core->prepareImport(b,ids,id,stamp());return QJsonObject{{"payload",p},{"display",planText(p,labels)}};},[this](QJsonObject result,QString){plan=result["payload"].toObject();ack->setChecked(false);showText(result["display"].toString());});});
 connect(cancelButton,&QPushButton::clicked,this,[this]{cancelPreview();});
 connect(beginButton,&QPushButton::clicked,this,[this]{if(!active||!isVisible()||!beginButton->isEnabled()||!ack->isChecked())return;auto core=coordinator;auto p=plan;run({true,p["selectedDomainIds"].toArray().contains("watchlist-config")},[core,p]{auto op=core->begin(p,true);return QJsonObject{{"payload",op},{"display",receiptText(op)}};},[this](QJsonObject result,QString){started=true;canContinue=true;showText(result["display"].toString());});});
 connect(nextButton,&QPushButton::clicked,this,[this]{auto core=coordinator;run({true,plan["selectedDomainIds"].toArray().contains("watchlist-config")},[core]{auto op=core->step();return QJsonObject{{"payload",op},{"display",receiptText(op)}};},[this](QJsonObject result,QString){auto op=result["payload"].toObject();canContinue=op["state"]=="ready"||op["state"]=="running";showText(result["display"].toString());});});
 connect(stopButton,&QPushButton::clicked,this,[this]{auto core=coordinator;run({true,false},[core]{auto op=core->stop();return QJsonObject{{"payload",op},{"display",receiptText(op)}};},[this](QJsonObject result,QString){canContinue=false;showText(result["display"].toString());});});
 connect(readButton,&QPushButton::clicked,this,[this]{auto core=coordinator;run({false,true},[core]{auto result=core->rereadReceipt();auto op=result["receipt"].toObject();QString text=receiptText(op);for(auto v:result["observations"].toArray()){auto o=v.toObject();text+="\n"+hostDomain(o["id"].toString())+"：结果未确认；"+observation(o["observation"].toString());}return QJsonObject{{"state",op["state"]},{"display",text}};},[this](QJsonObject result,QString){if(result["state"]!="ready"&&result["state"]!="running")canContinue=false;showText(result["display"].toString());});});
 showText("尚未读取数据。");refresh();
}
QJsonArray Page::selected()const{QJsonArray ids;for(auto p:choices)if(p->isChecked())ids.append(p->objectName());return ids;}
void Page::refresh(){bool idle=active&&!busy&&bool(runner),has=!selected().isEmpty(),exportable=has;for(auto p:choices){if(p->isChecked())exportable&=p->property("exportReady").toBool();p->setEnabled(active&&!writing&&!started);}
 exportButton->setEnabled(idle&&!started&&exportable&&bool(receiveExport));openButton->setEnabled(idle&&!started&&bool(chooseFile));previewButton->setEnabled(idle&&!started&&has&&!bundle.isEmpty());cancelButton->setEnabled(active&&!writing&&!started&&(busy||!plan.isEmpty()||!bundle.isEmpty()));ack->setEnabled(idle&&!started&&plan["canConfirm"]==true);beginButton->setEnabled(idle&&!started&&ack->isChecked()&&plan["canConfirm"]==true&&coordinator->canJournal());nextButton->setEnabled(idle&&started&&canContinue);stopButton->setEnabled(idle&&started&&canContinue);readButton->setEnabled(idle&&coordinator->canJournal());
}
void Page::run(Task task,Work work,Done done){if(busy||!runner||!active)return;if(!task.writing&&onInvalidate)onInvalidate();busy=true;writing=task.writing;if(writing)showText("正在写入并核验回执；离开或取消不会撤销已开始的操作。");refresh();QPointer<Page> guard(this);auto finish=[guard,done](QJsonObject value,QString error){if(!guard)return;guard->busy=false;guard->writing=false;if(!error.isEmpty()){guard->plan={};guard->ack->setChecked(false);guard->canContinue=false;guard->showText("操作未确认："+error+"\n不会自动重试；已开始写入的结果请查回执。");}else try{done(value,{});}catch(const std::exception&e){guard->canContinue=false;guard->showText(QString::fromUtf8(e.what()));}guard->refresh();};try{runner(task,std::move(work),finish);}catch(const std::exception&e){finish({},QString::fromUtf8(e.what()));}}
void Page::acceptBytes(QByteArray bytes){if(started||busy||!active)return;plan={};bundle={};ack->setChecked(false);run({false,false},[bytes]{auto b=decode(bytes);return QJsonObject{{"payload",b},{"display",importText(b)}};},[this](QJsonObject r,QString){acceptPrepared(r["payload"].toObject(),r["display"].toString());});}
bool Page::startImport(){if(started||busy||!active)return false;lane->invalidate();if(onInvalidate)onInvalidate();bundle={};plan={};ack->setChecked(false);showText("正在读取所选文件；旧预览已失效。");refresh();return true;}
void Page::acceptPrepared(QJsonObject b,QString summary){if(started||!active)return;bundle=std::move(b);plan={};ack->setChecked(false);showText(summary);refresh();}
QString Page::importText(QJsonObject b){QStringList ids;for(auto v:b["selectedDomainIds"].toArray())ids<<hostDomain(v.toString());return "文件校验通过，尚未恢复。\n来源版本："+b["producerVersion"].toString()+"\n备份时点："+b["createdAt"].toString()+"\n包含："+ids.join("、")+"\n请选择要恢复的项后预览；仅归档项无法恢复。";}
void Page::cancelPreview(){if(writing){showText("写入已开始；取消不会回滚。请等待并核对回执。");return;}lane->invalidate();if(onInvalidate)onInvalidate();if(!started)plan={};ack->setChecked(false);showText(busy?"预览已取消，等待后台释放资源；晚到结果不会接受。":"已取消预览；未开始写入。");refresh();}
void Page::setActive(bool value){active=value;lane->setActive(value);if(!value&&onInvalidate)onInvalidate();if(!value&&!writing&&!started){plan={};ack->setChecked(false);}refresh();}
void Page::showReceiptInspection(QString text){if(!active||busy)return;if(!started){plan={};ack->setChecked(false);}showText(std::move(text));refresh();}
void Page::showText(QString text){fullText=std::move(text);textOffset=0;renderText();}
void Page::renderText(){auto total=fullText.size();if(textOffset>=total)textOffset=0;details->setPlainText(fullText.mid(textOffset,32768));previousText->setEnabled(textOffset>0);nextText->setEnabled(textOffset+32768<total);details->setToolTip(QString("完整文本共 %1 字符；当前 %2 至 %3，分段显示，不截断原文").arg(total).arg(textOffset+1).arg(qMin<qsizetype>(total,textOffset+32768)));}
static QString planText(QJsonObject p,const QMap<QString,QString>& names){QString out="逐项预览 · "+p["operationId"].toString()+"\n确认后先保存恢复前备份，再逐项执行。\n";if(!p["journalReady"].toBool())out+="回执保存尚未接入，确认禁用。\n";for(auto v:p["domains"].toArray()){auto r=v.toObject();out+="\n"+names.value(r["id"].toString(),r["id"].toString())+"："+stateLabel(r["state"].toString())+"\n"+r["reason"].toString();out+=::recentRestore::describeOperationRow(r)+::businessRestore::describeOperationRow(r);out+=::observationRestore::describeOperationRow(r);out+=::candidateRestore::describe(r);out+=::industryArchive::describeOperationRow(r);auto owner=r["preview"].toObject()["owner"].toObject();if(owner.contains("change"))out+=describe(owner["change"].toObject());else if(owner.contains("addedBoards")){out+=QString("\n新增板块 %1，新增候选 %2，身份待核对 %3\n").arg(owner["addedBoards"].toInt()).arg(owner["addedLeaders"].toInt()).arg(owner["unresolvedCount"].toInt());for(auto x:owner["conflicts"].toArray())out+=x.toString()+"\n";for(auto x:owner["config"].toObject()["sectors"].toArray()){auto b=x.toObject();out+="合并后板块："+b["name"].toString()+" · "+b["description"].toString()+"\n";for(auto y:b["leaders"].toArray()){auto l=y.toObject();out+=l["name"].toString()+" "+l["code"].toString()+" "+l["fullId"].toString()+" "+l["role"].toString()+" · 权重 "+QString::number(l["weight"].toDouble(),'g',17)+"\n"+l["reason"].toString()+" "+l["note"].toString()+"\n";}}}}return out;}
static QString receiptText(QJsonObject op){if(op.isEmpty())return "没有已保存的操作回执。";QString out="本次操作："+stateLabel(op["state"].toString())+"\n不同模块分别提交。恢复前备份与逐项状态保存在操作回执中。\n";if(op.contains("journalError"))out+="回执保存失败："+op["journalError"].toString()+"\n此结果未持久保存，必须重读；禁止继续。\n";for(auto v:op["domains"].toArray()){auto r=v.toObject();out+=r["id"].toString()+"："+stateLabel(r["state"].toString())+" "+r["reason"].toString()+"\n";out+=::recentRestore::describeOperationRow(r)+::businessRestore::describeOperationRow(r);out+=::observationRestore::describeOperationRow(r);out+=::candidateRestore::describe(r);out+=::industryArchive::describeOperationRow(r);}return out;}
}
